#include <cuda_runtime.h>
#include <vector>
#include <array>
#include <fstream>
#include <cstring>
#include <cmath>
#include <chrono>
#include "../lda-cuda/kernel.h"
const float FSENT=-8192.25f;const int ISENT=-123456789;const unsigned char BSENT=0xa5;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>load(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);size_t n=size_t(f.tellg());std::vector<double>v(n/8);f.seekg(0);f.read((char*)v.data(),n);return v;}
template<class T>struct Buffer{int n;T sent;std::vector<T>h;T*d;void init(const std::vector<double>&v,T s){n=int(v.size());sent=s;h.assign(n+8,s);for(int i=0;i<n;i++)h[i+4]=T(v[i]);ck(cudaMalloc(&d,h.size()*sizeof(T)));upload();}void upload(){ck(cudaMemcpy(d,h.data(),h.size()*sizeof(T),cudaMemcpyHostToDevice));}void reset(T v){std::fill(h.begin()+4,h.end()-4,v);upload();}void set(const std::vector<double>&v){for(int i=0;i<n;i++)h[i+4]=T(v[i]);upload();}std::vector<T>capture(bool exact,std::vector<double>&out,bool&ok){std::vector<T>b(n+8);ck(cudaMemcpy(b.data(),d,b.size()*sizeof(T),cudaMemcpyDeviceToHost));if(exact)ok&=memcmp(b.data(),h.data(),b.size()*sizeof(T))==0;for(int j=0;j<4;j++)ok&=b[j]==sent&&b[n+4+j]==sent;for(T v:b)out.push_back(double(v));return b;}};
struct Case{int K,NW,D,blocks,iters,reps;std::array<Buffer<float>,8>F;std::array<Buffer<int>,3>I;Buffer<unsigned char>M;std::vector<double>trainmask,valmask;};
void reset(Case&c){c.F[3].reset(FSENT);for(int j=4;j<8;j++)c.F[j].reset(0.f);c.I[2].reset(0);c.M.set(c.trainmask);}
void run(Case&c,bool init){auto&F=c.F;auto&I=c.I;EstepKernel<<<c.blocks,256,4*c.K*sizeof(float)>>>(I[0].d+4,I[1].d+4,(const bool*)(c.M.d+4),F[0].d+4,init,c.NW,c.D,c.K,c.iters,F[1].d+4,F[2].d+4,F[3].d+4,F[4].d+4,F[5].d+4,F[6].d+4,F[7].d+4,I[2].d+4);ck(cudaGetLastError());}
using Back=std::array<std::vector<float>,8>;
Back snapshot(Case&c,const std::vector<double>&oracle,size_t&oi,std::vector<double>&payload,int phase,const Back*train,bool&ok,double&err,double&masserr){c.I[0].capture(true,payload,ok);c.I[1].capture(true,payload,ok);c.M.capture(true,payload,ok);Back b;for(int j=0;j<8;j++){b[j]=c.F[j].capture(j<3,payload,ok);if(j>=3){for(int i=0;i<c.F[j].n;i++){double value=b[j][i+4],ref=oracle[oi++],e=fabs(value-ref);err=fmax(err,e);ok&=std::isfinite(value)&&e<=2e-5+1e-4*fabs(ref);}}}auto locks=c.I[2].capture(true,payload,ok);double alphasum=0;for(int t=0;t<c.K;t++)alphasum+=c.F[1].h[t+4];for(int doc=0;doc<c.D;doc++){double target=alphasum;if(phase==0){int beg=c.I[1].h[doc+4],end=c.I[1].h[doc+5];for(int k=beg;k<end;k++)target+=c.F[0].h[k+4];}double sum=0;for(int t=0;t<c.K;t++){sum+=b[3][4+doc*c.K+t];if(phase==1)ok&=memcmp(&b[3][4+doc*c.K+t],&c.F[1].h[t+4],4)==0;}double e=fabs(sum-target);masserr=fmax(masserr,e);ok&=e<=2e-4;}
for(int w=0;w<c.NW;w++){double sum=0;for(int t=0;t<c.K;t++){float v=b[5][4+w*c.K+t];sum+=v;if(w==c.NW-1)ok&=v==0.f;}if(w<c.NW-1){double e=fabs(sum-c.reps*double(c.F[0].h[w+4]));masserr=fmax(masserr,e);ok&=e<=2e-4;}}if(phase==1){ok&=memcmp(b[5].data(),(*train)[5].data(),b[5].size()*4)==0;ok&=memcmp(b[6].data(),(*train)[6].data(),b[6].size()*4)==0;}return b;}
int main(){auto f=load(LDA_FIXTURE),oracle=load(LDA_ORACLE);size_t pos=0;std::vector<Case>cases;auto take=[&](int n){std::vector<double>v(f.begin()+pos,f.begin()+pos+n);pos+=n;return v;};while(pos<f.size()){Case c;c.K=int(f[pos++]);c.NW=int(f[pos++]);c.D=int(f[pos++]);c.blocks=int(f[pos++]);c.iters=int(f[pos++]);c.reps=int(f[pos++]);auto alpha=take(c.K),beta=take(c.NW*c.K),cts=take(c.NW),cols=take(c.NW),ptr=take(c.D+1);c.trainmask=take(c.NW);c.valmask=take(c.NW);c.F[0].init(cts,FSENT);c.F[1].init(alpha,FSENT);c.F[2].init(beta,FSENT);c.F[3].init(std::vector<double>(c.D*c.K,FSENT),FSENT);c.F[4].init(std::vector<double>(c.blocks*c.K,0),FSENT);c.F[5].init(std::vector<double>(c.NW*c.K,0),FSENT);c.F[6].init(std::vector<double>(c.blocks,0),FSENT);c.F[7].init(std::vector<double>(c.blocks,0),FSENT);c.I[0].init(cols,ISENT);c.I[1].init(ptr,ISENT);c.I[2].init(std::vector<double>(c.NW,0),ISENT);c.M.init(c.trainmask,BSENT);cases.push_back(c);}
for(auto&c:cases){reset(c);for(int rep=0;rep<c.reps;rep++)run(c,rep==0);ck(cudaDeviceSynchronize());c.M.set(c.valmask);for(int rep=0;rep<c.reps;rep++)run(c,c.reps==1);ck(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){auto payload=f;std::vector<double>times;double elapsed=0,err=0,masserr=0;bool ok=true;size_t oi=0;for(auto&c:cases){reset(c);ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int rep=0;rep<c.reps;rep++)run(c,rep==0);ck(cudaDeviceSynchronize());double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/c.reps;times.push_back(t);elapsed+=t;Back train=snapshot(c,oracle,oi,payload,0,nullptr,ok,err,masserr);c.M.set(c.valmask);ck(cudaDeviceSynchronize());start=std::chrono::steady_clock::now();for(int rep=0;rep<c.reps;rep++)run(c,c.reps==1);ck(cudaDeviceSynchronize());t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/c.reps;times.push_back(t);elapsed+=t;snapshot(c,oracle,oi,payload,1,&train,ok,err,masserr);}
std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream out(path,std::ios::binary);out.write((char*)payload.data(),payload.size()*8);out.close();printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_mass_identity_residual\":%.17g,\"timing_region\":\"sum6_lda_train_validation_2launch_means_complete\",\"jit_excluded\":true,\"internal_repeats\":2,\"timed_kernel_calls\":12,\"case_phase_times_seconds\":[",trial,elapsed,ok?"true":"false",payload.size(),err,masserr);for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path.c_str(),payload.size());if(!ok)return 3;}
for(auto&c:cases){for(auto&b:c.F)ck(cudaFree(b.d));for(auto&b:c.I)ck(cudaFree(b.d));ck(cudaFree(c.M.d));}}
